// ledger #1096: SELF-HALT cut. Same loop as tb_looped_cordic_open_flex_v1.v, but after the 2nd result is acknowledged the feedback stops (the 3rd result is not acknowledged): the design must settle with the loop value held in the exit relay and nothing else in flight. Prints HALT and one BUSY line per non-constant cell still holding a word.
// ledger #1094: closes the open-ring looped CORDIC (nano/examples/looped_cordic_v1_open.icm-hier.json -> project_assemble -s flex, top icm_open_flex): result is fed back into z_input; prints every result.
`timescale 1ns/1ps
module tb;
  reg clk=0, rst=1, cfg=0; always #5 clk=~clk;
  reg started=0, inj=0; reg [31:0] z0=32'd50000;
  wire [31:0] od; wire ov; wire iack;
  wire halt = (n>=2);
  wire [31:0] idata = started ? od : z0;
  wire ivalid = started ? (ov & ~halt) : inj;
  wire oack = started ? (iack & ~halt) : 1'b0;
  icm_open_flex d(.clk(clk),.rst(rst),.cfg_valid(cfg),.in_z_input_data(idata),.in_z_input_valid(ivalid),.in_z_input_ack(iack),
                  .out_result_data(od),.out_result_valid(ov),.out_result_ack(oack));
  integer n=0, cyc=0, last=0;
  always @(posedge clk) begin
    cyc <= cyc+1;
    if (started && ov && oack) begin
      n <= n+1; $display("R %0d %0d %0d", n+1, $signed(od), cyc-last); last <= cyc;
      
    end
    if (!started && inj && iack) begin started <= 1; inj <= 0; last <= cyc; end
  end
  initial begin
    repeat(4) @(posedge clk); rst<=0; @(posedge clk); cfg<=1; @(posedge clk); cfg<=0;
    repeat(30) @(posedge clk); inj<=1;
    repeat(400) @(posedge clk); $display("HALT n=%0d od=%0d ov=%0d",n,$signed(od),ov); if (d.c_lp_drift_const.fixed_mode==0 && d.c_lp_drift_const.pending) $display("BUSY c_lp_drift_const"); if (d.c_s0_branch.pending_1|d.c_s0_branch.pending_2) $display("BUSY c_s0_branch"); if (d.c_s0_const_neg.fixed_mode==0 && d.c_s0_const_neg.pending) $display("BUSY c_s0_const_neg"); if (d.c_s0_const_pos.fixed_mode==0 && d.c_s0_const_pos.pending) $display("BUSY c_s0_const_pos"); if (d.c_s0_zero_source.fixed_mode==0 && d.c_s0_zero_source.pending) $display("BUSY c_s0_zero_source"); if (d.c_s1_const_neg.fixed_mode==0 && d.c_s1_const_neg.pending) $display("BUSY c_s1_const_neg"); if (d.c_s1_const_pos.fixed_mode==0 && d.c_s1_const_pos.pending) $display("BUSY c_s1_const_pos"); if (d.c_s1_zero_source.fixed_mode==0 && d.c_s1_zero_source.pending) $display("BUSY c_s1_zero_source"); if (d.c_s2_const_neg.fixed_mode==0 && d.c_s2_const_neg.pending) $display("BUSY c_s2_const_neg"); if (d.c_s2_const_pos.fixed_mode==0 && d.c_s2_const_pos.pending) $display("BUSY c_s2_const_pos"); if (d.c_s2_zero_source.fixed_mode==0 && d.c_s2_zero_source.pending) $display("BUSY c_s2_zero_source"); if (d.c_s3_const_neg.fixed_mode==0 && d.c_s3_const_neg.pending) $display("BUSY c_s3_const_neg"); if (d.c_s3_const_pos.fixed_mode==0 && d.c_s3_const_pos.pending) $display("BUSY c_s3_const_pos"); if (d.c_s3_zero_source.fixed_mode==0 && d.c_s3_zero_source.pending) $display("BUSY c_s3_zero_source"); if (d.c_s0_add_neg.pending) $display("BUSY c_s0_add_neg"); if (d.c_s0_add_pos.pending) $display("BUSY c_s0_add_pos"); if (d.c_s0_turn_neg.fixed_mode==0 && d.c_s0_turn_neg.pending) $display("BUSY c_s0_turn_neg"); if (d.c_s0_turn_pos.fixed_mode==0 && d.c_s0_turn_pos.pending) $display("BUSY c_s0_turn_pos"); if (d.c_s0_gather_merge.pending) $display("BUSY c_s0_gather_merge"); if (d.c_s0_gather.fixed_mode==0 && d.c_s0_gather.pending) $display("BUSY c_s0_gather"); if (d.c_s1_branch.pending_1|d.c_s1_branch.pending_2) $display("BUSY c_s1_branch"); if (d.c_s1_add_neg.pending) $display("BUSY c_s1_add_neg"); if (d.c_s1_add_pos.pending) $display("BUSY c_s1_add_pos"); if (d.c_s1_turn_neg.fixed_mode==0 && d.c_s1_turn_neg.pending) $display("BUSY c_s1_turn_neg"); if (d.c_s1_turn_pos.fixed_mode==0 && d.c_s1_turn_pos.pending) $display("BUSY c_s1_turn_pos"); if (d.c_s1_gather_merge.pending) $display("BUSY c_s1_gather_merge"); if (d.c_s1_gather.fixed_mode==0 && d.c_s1_gather.pending) $display("BUSY c_s1_gather"); if (d.c_s2_branch.pending_1|d.c_s2_branch.pending_2) $display("BUSY c_s2_branch"); if (d.c_s2_add_neg.pending) $display("BUSY c_s2_add_neg"); if (d.c_s2_add_pos.pending) $display("BUSY c_s2_add_pos"); if (d.c_s2_turn_neg.fixed_mode==0 && d.c_s2_turn_neg.pending) $display("BUSY c_s2_turn_neg"); if (d.c_s2_turn_pos.fixed_mode==0 && d.c_s2_turn_pos.pending) $display("BUSY c_s2_turn_pos"); if (d.c_s2_gather_merge.pending) $display("BUSY c_s2_gather_merge"); if (d.c_s2_gather.fixed_mode==0 && d.c_s2_gather.pending) $display("BUSY c_s2_gather"); if (d.c_s3_branch.pending_1|d.c_s3_branch.pending_2) $display("BUSY c_s3_branch"); if (d.c_s3_add_neg.pending) $display("BUSY c_s3_add_neg"); if (d.c_s3_add_pos.pending) $display("BUSY c_s3_add_pos"); if (d.c_s3_turn_neg.fixed_mode==0 && d.c_s3_turn_neg.pending) $display("BUSY c_s3_turn_neg"); if (d.c_s3_turn_pos.fixed_mode==0 && d.c_s3_turn_pos.pending) $display("BUSY c_s3_turn_pos"); if (d.c_s3_gather_merge.pending) $display("BUSY c_s3_gather_merge"); if (d.c_s3_gather.fixed_mode==0 && d.c_s3_gather.pending) $display("BUSY c_s3_gather"); if (d.c_lp_fb0.fixed_mode==0 && d.c_lp_fb0.pending) $display("BUSY c_lp_fb0"); if (d.c_lp_fb1.fixed_mode==0 && d.c_lp_fb1.pending) $display("BUSY c_lp_fb1"); if (d.c_lp_fb2.fixed_mode==0 && d.c_lp_fb2.pending) $display("BUSY c_lp_fb2"); if (d.c_lp_fb3.fixed_mode==0 && d.c_lp_fb3.pending) $display("BUSY c_lp_fb3"); if (d.c_lp_fb4.fixed_mode==0 && d.c_lp_fb4.pending) $display("BUSY c_lp_fb4"); if (d.c_lp_fb5.fixed_mode==0 && d.c_lp_fb5.pending) $display("BUSY c_lp_fb5"); if (d.c_lp_fb6.fixed_mode==0 && d.c_lp_fb6.pending) $display("BUSY c_lp_fb6"); if (d.c_lp_fb7.fixed_mode==0 && d.c_lp_fb7.pending) $display("BUSY c_lp_fb7"); if (d.c_lp_fb8.fixed_mode==0 && d.c_lp_fb8.pending) $display("BUSY c_lp_fb8"); if (d.c_lp_drift_add.pending) $display("BUSY c_lp_drift_add"); if (d.c_lp_fb10.fixed_mode==0 && d.c_lp_fb10.pending) $display("BUSY c_lp_fb10"); if (d.c_lp_fb11.fixed_mode==0 && d.c_lp_fb11.pending) $display("BUSY c_lp_fb11"); if (d.c_lp_fb12.fixed_mode==0 && d.c_lp_fb12.pending) $display("BUSY c_lp_fb12"); if (d.c_lp_fb13.fixed_mode==0 && d.c_lp_fb13.pending) $display("BUSY c_lp_fb13"); if (d.c_lp_fb14.fixed_mode==0 && d.c_lp_fb14.pending) $display("BUSY c_lp_fb14"); if (d.c_lp_fb15.fixed_mode==0 && d.c_lp_fb15.pending) $display("BUSY c_lp_fb15"); if (d.c_lp_fb16.fixed_mode==0 && d.c_lp_fb16.pending) $display("BUSY c_lp_fb16"); if (d.c_lp_fb17.fixed_mode==0 && d.c_lp_fb17.pending) $display("BUSY c_lp_fb17"); if (d.c_lp_fb18.fixed_mode==0 && d.c_lp_fb18.pending) $display("BUSY c_lp_fb18"); if (d.c_lp_fb19.fixed_mode==0 && d.c_lp_fb19.pending) $display("BUSY c_lp_fb19"); $finish;
  end
endmodule
